contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    // single public test entry
    function run(address payable deployerOwner, address payable recipient, uint amount) public payable {
        require(address(this).balance >= amount);
        // The checker deploys a fresh C with constructor arg deployerOwner already done.
        // Observe initial owner and contract balance
        address ownerBefore = c.owner();
        uint balanceBefore = address(c).balance;

        // If this test contract is the owner, a withdraw by this contract should succeed and transfer full balance to recipient
        bool reverted;
        try c.withdrawAll(recipient) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // After the call, either it reverted and balances unchanged, or it succeeded and contract balance is zero and recipient got the funds
        if (reverted) {
            // If reverted, contract balance must be unchanged
            assert(address(c).balance == balanceBefore);
        } else {
            // If not reverted, caller must have been owner and contract balance must have gone to zero
            assert(ownerBefore == address(this));
            assert(address(c).balance == 0);
        }
    }

    // allow receiving ether if needed by tests
    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address payable recipient, uint amount) public payable {
        require(address(this).balance >= amount);
        // record pre-call observable state
        address ownerBefore = c.owner();
        uint balanceBefore = address(c).balance;

        // perform the state-changing call as its own top-level statement
        bool callSucceeded;
        // call may revert; capture success without try by using low-level call
        (callSucceeded, ) = address(c).call(abi.encodeWithSignature("withdrawAll(address)", recipient));

        // After the call: either it succeeded -> caller must be ownerBefore and contract balance zero;
        // or it failed -> contract balance unchanged.
        assert( (callSucceeded && ownerBefore == address(this) && address(c).balance == 0) || (!callSucceeded && address(c).balance == balanceBefore) );
    }
    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function
    function run(address payable recipient, uint sendAmount) public payable {
        // ensure this test contract has enough Ether to fund c if desired
        require(address(this).balance >= sendAmount);

        // record observable state before interactions
        address ownerBefore = c.owner();
        uint balanceBefore = address(c).balance;

        // optionally seed c with Ether by sending sendAmount
        if (sendAmount > 0) {
            // top-level state-changing call to c: fallback payable
            c.fallback{value: sendAmount}();
        }

        // After optionally funding, update expected balanceBefore to include sendAmount
        uint balanceAfterFund = address(c).balance;

        // Now attempt withdrawAll as a top-level call; capture revert with try/catch
        bool reverted;
        try c.withdrawAll(recipient) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Observables after call
        uint balanceFinal = address(c).balance;
        address ownerAfter = c.owner();

        // Assert the general rule:
        // - owner field never changes due to withdrawAll call
        // - if call succeeded (not reverted) then msg.sender was equal to ownerBefore and contract balance became zero
        // - if call reverted then contract balance unchanged from immediately-before-withdraw
        assert(
            ownerAfter == ownerBefore
            && (
                (!reverted && ownerBefore == address(this) && balanceFinal == 0)
                || (reverted && balanceFinal == balanceAfterFund)
            )
        );
    }

    // allow test contract to receive Ether
    receive() external payable { }

    // forward to c payable fallback via an explicit external call signature
    // Note: to satisfy the requirement that state-changing calls on c are top-level and direct,
    // we rely on c having a payable fallback and call it above as c.fallback{value: amount}();
}

