contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // run takes an address _ownerCandidate (to compare with c.owner()),
    // a recipient to withdraw to, and an amount to fund c with prior to withdrawal.
    function run(address _ownerCandidate, address payable _recipient, uint256 fundAmount) public payable {
        require(address(this).balance >= fundAmount);

        // fund the contract c with fundAmount wei from this test contract
        // using the fallback payable of C
        (bool sent,) = address(c).call{value: fundAmount}("");
        require(sent);

        // read observable before-values
        address owner = c.owner();
        uint256 beforeCbal = address(c).balance;
        uint256 beforeRecipientBal = _recipient.balance;

        // attempt withdrawAll and record whether it reverted
        bool reverted;
        try c.withdrawAll(_recipient) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 afterCbal = address(c).balance;
        uint256 afterRecipientBal = _recipient.balance;

        // General rule:
        // If the call did not revert then the caller must have been the owner (i.e., owner == address(this))
        // AND the contract's balance becomes zero AND the recipient's balance increases by exactly beforeCbal.
        // If it reverted then either the caller was not the owner or balances remain unchanged.
        assert(
            (
                !reverted
                && owner == address(this)
                && afterCbal == 0
                && afterRecipientBal == beforeRecipientBal + beforeCbal
            )
            ||
            (
                reverted
                && (owner != address(this) || afterCbal == beforeCbal)
            )
        );
    }

    receive() external payable {}
}

