contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // run takes an address _owner to initialize C (already deployed by harness),
    // a recipient to pass to withdrawAll, and an amount to first fund C via fallback.
    function run(address _owner, address payable _recipient, uint256 fundAmount) public payable {
        require(address(this).balance >= fundAmount);

        // Observe initial owner and balances
        address beforeOwner = c.owner();
        uint256 beforeBalanceC = address(c).balance;
        uint256 beforeBalanceThis = address(this).balance;

        // Fund c by sending Ether to it so there's something to withdraw. Use a direct call to fallback.
        // Must ensure we have the funds in this contract
        (bool sent,) = address(c).call{value: fundAmount}("");
        // treat send failure as revert for test purposes
        if (!sent) { revert("funding failed"); }

        uint256 afterFundBalanceC = address(c).balance;

        // Decide who is owner for the purpose of calling withdrawAll:
        // If this contract equals owner, call will succeed; otherwise it should revert.
        bool callReverted;
        uint256 balThisBeforeWithdraw = address(this).balance;
        uint256 balCBeforeWithdraw = address(c).balance;
        try c.withdrawAll(_recipient) {
            callReverted = false;
        } catch {
            callReverted = true;
        }

        uint256 balCAfter = address(c).balance;
        uint256 balRecipientAfter = _recipient.balance;

        // General rule:
        // If this contract is the owner at time of call, the call must not revert and contract balance becomes 0
        // and recipient's balance increases by the withdrawn amount; otherwise the call reverts and balances stay the same.
        if (beforeOwner == address(this)) {
            assert(callReverted == false && balCAfter == 0 && balRecipientAfter >= balCBeforeWithdraw);
        } else {
            assert(callReverted == true && balCAfter == balCBeforeWithdraw && balRecipientAfter == balRecipientAfter - 0 + 0);
        }
    }

    receive() external payable { }
}

