contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    // run takes parameters: caller (address) used to set owner at deployment of C already done by harness;
    // we cannot redeploy c here. But we can call withdrawAll as this contract (msg.sender == address(this)).
    // So we take a candidateRecipient and an amount to send into c before testing.
    function run(address payable recipient, uint256 fundAmount) public payable {
        require(address(this).balance >= fundAmount);
        // fundAmount is sent to c to create a non-zero balance to withdraw
        (bool sent,) = address(c).call{value: fundAmount}("");
        // read balances before withdraw
        uint256 beforeC = address(c).balance;
        uint256 beforeRecipient = recipient.balance;
        // perform withdrawAll and catch revert
        bool reverted;
        try c.withdrawAll(recipient) {
            reverted = false;
        } catch {
            reverted = true;
        }
        // read balances after
        uint256 afterC = address(c).balance;
        uint256 afterRecipient = recipient.balance;
        // If the call reverted, contract balance must be unchanged and recipient balance unchanged.
        // If it did not revert, then the entire c balance must have been transferred to recipient
        // (afterC == 0 and afterRecipient - beforeRecipient == beforeC).
        assert(reverted ? (afterC == beforeC && afterRecipient == beforeRecipient) : (afterC == 0 && afterRecipient - beforeRecipient == beforeC));
    }
    receive() external payable {}
}

