    // - deployer: address that was passed as owner when c was constructed (unknown to this test);
    // We take as parameters the caller (who will be msg.sender to c via this contract's call) by
    // specifying a boolean as to whether we attempt the withdraw as owner or non-owner, and an
    // amount of Ether to send to c beforehand so there is a balance to withdraw, and a recipient.

    // Note: We cannot create arbitrary callers to c other than this contract; c's owner was set at
    // deployment time externally. To simulate owner vs non-owner behavior, we use the publicly
    // visible c.owner() value: if we call withdrawAll from this contract and this contract equals
    // c.owner(), the call should succeed; otherwise it should revert. The test thus parametrizes
    // recipient and amount and asserts the general invariant about balances and revert behavior.

    function run(address payable recipient, uint256 fundAmount) public payable {
        require(address(this).balance >= fundAmount);

        // Fund c by sending Ether to its fallback
        (bool sent,) = address(c).call{value: fundAmount}("");
        // the funding itself should succeed (fallback is payable)
        require(sent);

        // Read balance before
        uint256 before = address(c).balance;
        // Ensure before equals fundAmount (freshly deployed c may have had 0)
        // But we do not require it equals anything; just record.

        bool reverted;
        // Attempt withdrawAll from this contract (msg.sender will be this contract)
        try c.withdrawAll(recipient) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 after = address(c).balance;

        // General rule:
        // - If this contract is the owner (c.owner() == address(this)), the call must not revert and
        //   the contract's balance must become zero, and recipient must have received the funds
        //   (we can observe by address(this).balance increase only if recipient == address(this)).
        // - If this contract is not the owner, the call must revert and c's balance must be unchanged.
        // We cannot directly observe recipient's balance for arbitrary recipient, so we assert the
        // balance-change properties which fully characterize withdrawAll's intended behavior.

        if (c.owner() == address(this)) {
            // owner case: should not revert and drain all funds
            assert(reverted == false && after == 0);
        } else {
            // non-owner case: should revert and leave balance unchanged
            assert(reverted == true && after == before);
        }
    }

