    // run takes: caller (address to act as owner or non-owner by passing as initial owner when c was deployed),
    // recipient to receive funds on withdraw, and amount to fund C before withdrawal.
    function run(address initialOwner, address payable recipient, uint256 fundAmount) public payable {
        require(address(this).balance >= fundAmount);

        // Observables before funding/withdrawal
        uint256 beforeBalance = address(c).balance;
        address contractOwner = c.owner();

        // fund the contract c from this test contract
        // send fundAmount to c using its fallback (payable)
        (bool sent,) = address(c).call{value: fundAmount}("");
        // ensure funding attempt succeeded for the purpose of reasoning about outcomes
        require(sent);

        uint256 afterFundBalance = address(c).balance;

        // Decide caller identity: we cannot change msg.sender for calls, but owner was set at c construction.
        // The test checks behavior for the actual owner recorded in c.owner(). We will attempt withdrawAll
        // and record whether it reverts. Calls that change state must be top-level.
        bool reverted;
        try c.withdrawAll(recipient) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // After attempted withdrawal observe balances
        uint256 finalContractBalance = address(c).balance;
        uint256 finalThisBalance = address(this).balance;

        // General rule:
        // - If msg.sender (this contract) is equal to c.owner() then withdrawAll must not revert and
        //   the contract's entire balance must have been sent to recipient (so final contract balance == 0
        //   and this contract's balance unchanged except for gas — but we cannot observe recipient's balance here,
        //   so we assert that contract's balance went to zero). However recipient could be arbitrary; we only
        //   observe contract balance. If withdraw was attempted by non-owner it must revert and balance unchanged.
        // Because this test runs with msg.sender == address(this), the condition depends on whether contractOwner == address(this).

        assert((contractOwner == address(this) && reverted == false && finalContractBalance == 0)
               || (contractOwner != address(this) && reverted == true && finalContractBalance == afterFundBalance));
    }

    // allow receiving ETH if needed
    receive() external payable {}
